-- 03_seed_demo.sql  (DEMO DATA ONLY - generated)
-- Runs after 01_schema.sql and 02_seed.sql. Replaces the two sample places from 02_seed.sql.
--
-- IMPORTANT ABOUT ACCURACY
--  * Place names are real landmarks, but coordinates are APPROXIMATE (typed from memory, not surveyed).
--  * Hours are typical/indicative and MUST be verified before real use. Every place is tagged 'demo-data'.
--  * distance_m / duration_* are ESTIMATES: straight-line distance x 1.4 road factor, average city speeds.
--    Real values must be recomputed with a routing provider (see the importer/recompute job).
--  * Hotel locations are approximate. 'Mysuru Heritage Lodge' is a fictional property.
--  * No phone numbers, ratings or photos are included on purpose (not verified).
--  * Places are stored per organization (tenant), so shared landmarks are duplicated per org by design.
-- To re-run: docker compose down -v && docker compose up -d   (init scripts only run on a fresh volume)

BEGIN;
DELETE FROM scan_events; DELETE FROM qr_codes; DELETE FROM audit_log;
DELETE FROM property_places;
DELETE FROM places WHERE organization_id IN ('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb');

-- Property details (coordinates approximate)
UPDATE properties SET lat=12.308, lng=76.653, wifi_name='Lodge-Guest', wifi_password='change-me', show_wifi=true, description='Fictional demo property for testing.' WHERE id='ffffffff-ffff-ffff-ffff-ffffffffffff';
UPDATE properties SET lat=12.9846, lng=77.5828, show_wifi=false, description='Demo property for testing.' WHERE id='cccccccc-cccc-cccc-cccc-cccccccccccc';
UPDATE properties SET lat=13.023, lng=77.5446, show_wifi=false, description='Demo property for testing.' WHERE id='dddddddd-dddd-dddd-dddd-dddddddddddd';
UPDATE properties SET lat=11.557, lng=76.041, show_wifi=false, description='Demo property for testing.' WHERE id='eeeeeeee-eeee-eeee-eeee-eeeeeeeeeeee';

-- Places

-- Links between properties and places with ESTIMATED distances

-- QR codes: two per property (lobby, rooms)
SELECT uuid_generate_v4(), p.id, v.code, v.label, '{"dots":"rounded","color":"#0F5C5C","logo":false}'::jsonb
FROM (VALUES
 ('ffffffff-ffff-ffff-ffff-ffffffffffff','MHL-LOBBY','Lobby'),('ffffffff-ffff-ffff-ffff-ffffffffffff','MHL-ROOMS','Rooms'),
 ('cccccccc-cccc-cccc-cccc-cccccccccccc','TWE-LOBBY','Lobby'),('cccccccc-cccc-cccc-cccc-cccccccccccc','TWE-ROOMS','Rooms'),
 ('dddddddd-dddd-dddd-dddd-dddddddddddd','TYP-LOBBY','Lobby'),('dddddddd-dddd-dddd-dddd-dddddddddddd','TYP-ROOMS','Rooms'),
 ('eeeeeeee-eeee-eeee-eeee-eeeeeeeeeeee','TWY-LOBBY','Lobby'),('eeeeeeee-eeee-eeee-eeee-eeeeeeeeeeee','TWY-ROOMS','Rooms')
) AS v(pid,code,label) JOIN properties p ON p.id = v.pid::uuid;

-- ~120 fake scan events per QR over the last 30 days (for analytics screens)
SELECT q.id, q.property_id,
       now() - (random() * interval '30 days'),
       (ARRAY['android','android','ios','ios','tablet','desktop'])[1 + floor(random()*6)::int],
       (ARRAY['en','en','en','hi','kn','ta'])[1 + floor(random()*6)::int]
FROM qr_codes q, generate_series(1,120) g;

-- A few audit entries so the audit log screen has content
COMMIT;
